/// The environment in which typesetting occurs.
///
/// All loading functions (`main`, `source`, `file`, `font`) should perform
/// internal caching so that they are relatively cheap on repeated invocations
/// with the same argument. [`Source`], [`Bytes`], and [`Font`] are
/// all reference-counted and thus cheap to clone.
///
/// The compiler doesn't do the caching itself because the world has much more
/// information on when something can change. For example, fonts typically don't
/// change and can thus even be cached across multiple compilations (for
/// long-running applications like `typst watch`). Source files on the other
/// hand can change and should thus be cleared after each compilation. Advanced
/// clients like language servers can also retain the source files and
/// [edit](Source::edit) them in-place to benefit from better incremental
/// performance.
#[comemo::track]
pub trait World: Send + Sync {
    /// The standard library.
    ///
    /// Can be created through `Library::build()`.
    fn library(&self) -> &LazyHash;

    /// Metadata about all known fonts.
    fn book(&self) -> &LazyHash;

    /// Get the file id of the main source file.
    fn main(&self) -> FileId;

    /// Try to access the specified file location as a source file.
    fn source(&self, id: FileId) -> FileResult;

    /// Try to access the specified file.
    ///
    /// For file locations for which [`source`](Self::source) succeeds, this
    /// should also succeed. The [`Bytes`] can be cheaply created as a view into
    /// an existing [`Source`] through [`Bytes::from_string`].
    fn file(&self, id: FileId) -> FileResult;

    /// Try to access the font with the given index in the font book.
    ///
    /// Note that the index is not guaranteed to be in bounds of the font book
    /// returned by this world's `book()` function. This is the case because
    /// this function may be invoked with indices from an outdated or different
    /// font book during incremental compilation validation.
    fn font(&self, index: usize) -> Option;

    /// Get the current date.
    ///
    /// If no offset is specified, the local date should be chosen. Otherwise,
    /// the UTC date should be chosen with the corresponding offset.
    ///
    /// If this function returns `None`, Typst's `datetime` function will
    /// return an error.
    fn today(&self, offset: Option) -> Option;
}

macro_rules! world_impl {
    ($W:ident for $ptr:ty) => {
        impl<$W: World> World for $ptr {
            fn library(&self) -> &LazyHash {
                self.deref().library()
            }

            fn book(&self) -> &LazyHash {
                self.deref().book()
            }

            fn main(&self) -> FileId {
                self.deref().main()
            }

            fn source(&self, id: FileId) -> FileResult {
                self.deref().source(id)
            }

            fn file(&self, id: FileId) -> FileResult {
                self.deref().file(id)
            }

            fn font(&self, index: usize) -> Option {
                self.deref().font(index)
            }

            fn today(&self, offset: Option) -> Option {
                self.deref().today(offset)
            }
        }
    };
}

world_impl!(W for std::boxed::Box);
world_impl!(W for std::sync::Arc);
world_impl!(W for &W);

/// Helper methods on [`World`] implementations.
pub trait WorldExt {
    /// Get the byte range for a span.
    ///
    /// Returns `None` if the `Span` does not point into any file.
    fn range(&self, span: impl Into) -> Option>;
}

impl WorldExt for T {
    fn range(&self, span: impl Into) -> Option> {
        match span.into().get() {
            DiagSpanKind::Detached => None,
            DiagSpanKind::Number { id, num, sub_range } => {
                self.source(id).ok()?.range(num, sub_range)
            }
            DiagSpanKind::Range { id: _, range } => Some(range),
        }
    }
}

/// Definition of Typst's standard library.
///
/// To create and configure the standard library, use the `LibraryExt` trait
/// and call
/// - `Library::default()` for a standard configuration
/// - `Library::builder().build()` if you want to customize the library
#[derive(Debug, Clone, Hash)]
#[non_exhaustive]
pub struct Library {
    /// Defines implementation of various Typst compiler routines as a table of
    /// function pointers.
    pub routines: &'static Routines,
    /// The module that contains the definitions that are available everywhere.
    pub global: Module,
    /// The module that contains the definitions available in math mode.
    pub math: Module,
    /// The default style properties (for page size, font selection, and
    /// everything else configurable via set and show rules).
    pub styles: Styles,
    /// The built-in show rules.
    pub rules: NativeRuleMap,
    /// The standard library as a value. Used to provide the `std` module.
    pub std: Binding,
    /// In-development features that were enabled.
    pub features: Features,
    /// Registered [export formats](crate::format).
    pub formats: Vec,
}

/// Configurable builder for the standard library.
///
/// Constructed via the `LibraryExt` trait.
#[derive(Debug, Clone)]
pub struct LibraryBuilder {
    routines: &'static Routines,
    inputs: Option,
    features: Features,
    formats: Vec,
}

impl LibraryBuilder {
    /// Creates a new builder.
    #[doc(hidden)]
    pub fn from_routines(
        routines: &'static Routines,
        formats: impl IntoIterator,
    ) -> Self {
        Self {
            routines,
            inputs: None,
            features: Features::default(),
            formats: formats.into_iter().collect(),
        }
    }

    /// Configure the inputs visible through `sys.inputs`.
    pub fn with_inputs(mut self, inputs: Dict) -> Self {
        self.inputs = Some(inputs);
        self
    }

    /// Configure in-development features that should be enabled.
    ///
    /// No guarantees whatsover!
    pub fn with_features(mut self, features: Features) -> Self {
        self.features = features;
        self
    }

    /// Consumes the builder and returns a `Library`.
    pub fn build(self) -> Library {
        let math = math::module();
        let inputs = self.inputs.unwrap_or_default();
        let global = global(&self.formats, math.clone(), inputs);
        let mut rules = (self.routines.rules)();
        for format in &self.formats {
            format.register_rules(&mut rules);
        }
        Library {
            routines: self.routines,
            global: global.clone(),
            math,
            styles: Styles::new(),
            rules,
            std: Binding::detached(global),
            features: self.features,
            formats: self.formats,
        }
    }
}

/// A selection of in-development features that should be enabled.
///
/// Can be collected from an iterator of [`Feature`]s.
#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
pub struct Features(SmallBitSet);

impl Features {
    /// Creates an instance where all features are enabled.
    pub fn all() -> Self {
        Feature::all().collect()
    }

    /// Creates an instance where no features are enabled.
    pub fn none() -> Self {
        Self::default()
    }

    /// Check whether the given feature is enabled.
    pub fn is_enabled(&self, feature: Feature) -> bool {
        self.0.contains(feature as usize)
    }
}

impl FromIterator for Features {
    fn from_iter>(iter: T) -> Self {
        let mut set = SmallBitSet::default();
        for feature in iter {
            set.insert(feature as usize);
        }
        Self(set)
    }
}

/// An in-development feature that should be enabled.
#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
#[non_exhaustive]
pub enum Feature {
    Html,
    Bundle,
    A11yExtras,
}

impl Feature {
    /// Iterates over all available features.
    pub fn all() -> impl Iterator {
        [Self::Html, Self::Bundle, Self::A11yExtras].into_iter()
    }
}

impl Display for Feature {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Feature::Html => "html",
            Feature::Bundle => "bundle",
            Feature::A11yExtras => "a11y-extras",
        })
    }
}

impl FromStr for Feature {
    type Err = ();

    fn from_str(s: &str) -> Result {
        match s {
            "html" => Ok(Self::Html),
            "bundle" => Ok(Self::Bundle),
            "a11y-extras" => Ok(Self::A11yExtras),
            _ => Err(()),
        }
    }
}

